import logging
import time
import json
import os
import openstack.orchestration.v1.stack
import openstack.resource
import openstack
from openstack.exceptions import ResourceNotFound
import requests
from typing import Union  # noqa: F401
from taf.config.testline.cloud_hosting import DeploymentVnfStack  # noqa: F401
from taf.config.testline.cloud_hosting import DeploymentNetworkStack  # noqa: F401
from taf.config.testline.cloud_hosting import DeploymentFlavorStack  # noqa: F401
from taf.config.testline.cloud_hosting import DeploymentSecurityGroupStack
from .yaml_helper import load_yaml, save_dict_as_yaml
from .exceptions import OpenstackException, Timeout
from .configuration import ConfigurationModifier
from .connection import verify_connection
from .exceptions import InvalidStatus
from taf.gnb.deployment.heat_templates.files import TemplateSerializer
from taf.cloud.openstack.stack_environment_store import PreparedEnvironments


class _Stack(openstack.orchestration.v1.stack.Stack):
    environment = openstack.resource.Body('environment')
    files = openstack.resource.Body('files')


class StackStatus(object):
    CREATE_ONGOING = 'CREATE_ONGOING'
    CREATE_COMPLETE = 'CREATE_COMPLETE'
    CREATE_FAILED = 'CREATE_FAILED'
    DELETE_ONGOING = 'DELETE_ONGOING'
    DELETE_COMPLETE = 'DELETE_COMPLETE'
    DELETE_FAILED = 'DELETE_FAILED'


class Stack(object):
    CHECK_INTERVAL = 2
    STACK_CREATE_IN_PROGRESS = "CREATE_IN_PROGRESS"
    STACK_CREATE_SUCCEEDED = "CREATE_COMPLETE"
    HEAT_TEMPLATE_VERSION = 'heat_template_version'
    ROBOT_ACCOUNT_PARAM_NAME = 'extra_cloud_config_data'
    DEFAULT_BTS_ENV_FILE_NAME = 'config_bts.env'
    STATUS_COMPLETE_SUFFIX = 'COMPLETE'
    STATUS_FAILED_SUFFIX = 'FAILED'

    def __init__(self, connection):
        verify_connection(connection)
        self.connection = connection

    def get_flavor_params(self, vnf_prefix=''):
        return {'parameters': {'vnf_prefix': vnf_prefix}} if vnf_prefix else {}

    def create_flavor_stack(self, stack_name, yaml_path, params={}, files={}):
        logging.info("Creating flavor stack")
        self._heat_create_stack(stack_name, yaml_path, params, files=files)

    def create_ext_net_stack(self, stack_name, yaml_path, params, files={}):
        logging.info("Creating ext_net stack")
        self._heat_create_stack(stack_name, yaml_path,
                                params=params, files=files)

    def create_deploy_stack(
            self, stack_name, yaml_path, params, files={}, inject_robot=False,
            robot_account_parameter_name=ROBOT_ACCOUNT_PARAM_NAME, bts_env_file_name=DEFAULT_BTS_ENV_FILE_NAME):
        logging.info("Creating deploy stack")
        res_registry = {'resource_registry': self._create_resource_registry(yaml_path, bts_env_file_name)}

        if inject_robot:
            ConfigurationModifier.inject_robot_account(
                params, robot_account_parameter_name)

        self._heat_create_stack(stack_name, yaml_path,
                                params=params, files=files,
                                resource_registry=res_registry)

    def _heat_create_stack(self, stack_name, yaml_path, params, files={},
                           resource_registry={}):
        template = load_yaml(yaml_path)
        if self.HEAT_TEMPLATE_VERSION in template:
            template[self.HEAT_TEMPLATE_VERSION] = str(
                template[self.HEAT_TEMPLATE_VERSION])
        heat = self.connection.orchestration

        attrs = {'stack_name': stack_name,
                 'template': template,
                 'files': files,
                 'environment': json.dumps(resource_registry)}
        attrs.update(params)

        stack = heat._create(_Stack, **attrs)
        self._wait_for_stack_creation(stack)

    def _wait_for_stack_creation(self, stack):
        heat = self.connection.orchestration
        while (not stack.status
               or stack.status == self.STACK_CREATE_IN_PROGRESS):
            logging.debug("Creating stack in progress")
            stack = heat.find_stack(stack.id)
            time.sleep(self.CHECK_INTERVAL)
        if stack.status != self.STACK_CREATE_SUCCEEDED:
            raise OpenstackException("Stack {} creation failed: {}".format(
                stack.name, stack.status_reason))

    def _get_status_with_deleted_if_missing(self, name_or_id):
        found_stack = self.find_stack(name_or_id, ignore_missing=True)
        if found_stack is None:
            stack_status = StackStatus.DELETE_COMPLETE
        else:
            stack_status = found_stack.status
        return stack_status

    def _get_status_reason(self, name_or_id):
        found_stack = self.find_stack(name_or_id, ignore_missing=True)
        if found_stack is None:
            status_reason = ''
        else:
            status_reason = found_stack.status_reason
        return status_reason

    def wait_for_stack_status(self, name_or_id, status, timeout):
        actual_status = None
        end = time.time() + timeout

        while time.time() < end:
            actual_status = self._get_status_with_deleted_if_missing(name_or_id)
            if actual_status == status:
                break

            self.fail_if_status_irrecoverable(status, actual_status)

            time.sleep(self.CHECK_INTERVAL)

        if actual_status != status:
            exc_msg = "Stack '{}' did not receive '{}' status after " \
                      "{} second(s). Actual status: '{}'.\n " \
                      "Actual status reason: '{}'."
            exc_msg = exc_msg.format(
                name_or_id,
                status,
                timeout,
                actual_status,
                self._get_status_reason(name_or_id))
            raise Timeout(exc_msg)

    def fail_if_status_irrecoverable(self, expected_status, actual_status):
        if (expected_status.endswith(self.STATUS_COMPLETE_SUFFIX)
                and actual_status.endswith(self.STATUS_FAILED_SUFFIX)):
            error_msg = 'Stack status: {}, requested status: {}'.format(actual_status, expected_status)
            raise InvalidStatus(error_msg)

    def remove_old_stacks_if_necessary(self, deploy_name, ext_net_name,
                                       flavors_name):
        def _remove_stack(msg, stack_name):
            logging.debug(msg)
            try:
                self._heat_remove_stack_by_name(stack_name, wait=True)
            except (AttributeError, OpenstackException):
                pass

        logging.info("Removing old stacks")
        _remove_stack("Removing deploy stack", deploy_name)
        _remove_stack("Removing ext stack", ext_net_name)
        _remove_stack("Removing flavor stack", flavors_name)

    def _heat_remove_stack_by_name(self, stack_name, wait):
        logging.debug("Removing stack {}".format(stack_name))
        if self.connection.delete_stack(stack_name, wait=wait):
            logging.info("Removed stack {}".format(stack_name))
        else:
            logging.info("Stack {} was not found".format(stack_name))

    def get_referenced_files(self, cfg_dir, templates_subdir='modules'):
        is_remote_file = cfg_dir.startswith("https://") or cfg_dir.startswith("http://")
        if is_remote_file:
            return self._get_referenced_files_from_url(cfg_dir, templates_subdir)
        else:
            return self._get_referenced_local_files(cfg_dir, templates_subdir)

    def _get_referenced_local_files(self, cfg_dir, templates_subdir='modules'):
        templ_dir = os.path.join(cfg_dir, templates_subdir)
        filenames = list(os.walk(templ_dir))[0][2]
        references = {}

        for fn in filenames:
            _templ_path = os.path.join(templ_dir, fn)
            templ_yaml = load_yaml(_templ_path)
            if self.HEAT_TEMPLATE_VERSION in templ_yaml:
                templ_yaml[self.HEAT_TEMPLATE_VERSION] = str(
                    templ_yaml[self.HEAT_TEMPLATE_VERSION])

            templ_content = json.dumps(templ_yaml)
            templ_relative_path = os.path.join(templates_subdir, fn)
            key = os.path.join(templ_relative_path)
            references[key] = templ_content

        return references

    def _get_referenced_files_from_url(self, config_files_url, templates_subdir="modules"):
        response = requests.get(config_files_url, verify=False)
        response.raise_for_status()
        resp_dict = response.json()['files']
        urls = {x['path']: x['_links']['content']['href'] for x in resp_dict if templates_subdir in x['path']}
        references = {}

        for templ_relative_path, url in urls.items():
            templ_yaml = load_yaml(url)
            if self.HEAT_TEMPLATE_VERSION in templ_yaml:
                templ_yaml[self.HEAT_TEMPLATE_VERSION] = str(
                    templ_yaml[self.HEAT_TEMPLATE_VERSION])

            templ_content = json.dumps(templ_yaml)
            key = templ_relative_path
            references[key] = templ_content

        return references

    def _create_resource_registry(self, yaml_path, bts_env_file_name):
        reader = TemplateSerializer()
        bts_env_file_path = os.path.join(os.path.dirname(yaml_path), bts_env_file_name)
        bts_env_content = reader.load(bts_env_file_path)
        return bts_env_content.get_value_from_template('resource_registry')

    def find_stack(self, name_or_id, ignore_missing=False):
        try:
            stack = self.connection.orchestration.find_stack(
                name_or_id=name_or_id, ignore_missing=ignore_missing)
        # TODO: AttributeError should be removed. openstacksdk throws
        # TODO: AttributeError when the stack is not found on newer openstack platform
        except AttributeError:
            if ignore_missing:
                return None
            else:
                raise ResourceNotFound('Stack {} was not found.'.format(name_or_id))
        return stack

    def get_status(self, name_or_id):
        # type: (str) -> str
        return self._get_status_with_deleted_if_missing(name_or_id)

    def remove(self, stack, wait=True):
        # type: (Union[DeploymentNetworkStack, DeploymentVnfStack, DeploymentFlavorStack, DeploymentSecurityGroupStack], bool) -> None
        try:
            self._heat_remove_stack_by_name(stack.name, wait=wait)
        # TODO: AttributeError should be removed. openstacksdk throws AttributeError
        # TODO: when the stack is not found on newer openstack platform
        except (AttributeError, OpenstackException):
            pass

    def create_stack(
            self,
            stack,  # type: Union[DeploymentNetworkStack, DeploymentVnfStack, DeploymentFlavorStack, DeploymentSecurityGroupStack]
            inject_robot=False,  # type: bool
            robot_account_parameter_name=ROBOT_ACCOUNT_PARAM_NAME,  # type: str
            wait=True,  # type: bool
            rollback=False  # type: bool
    ):
        # Make it backward compatible for clients that use configuration_data
        # TODO: remove legacy part in 3.0.0
        if stack.configuration_data is not None:
            warn_msg = "Using stack's `configuration_data` attribute is " \
                       "deprecated. Set this attribute to `None` to use the " \
                       "maintained create method."
            logging.warning(warn_msg)
            return self.create(
                stack=stack,
                inject_robot=inject_robot,
                robot_account_parameter_name=robot_account_parameter_name)
        else:
            if isinstance(stack, DeploymentVnfStack) and inject_robot:
                self._create_robot_account_in_file(
                    stack,
                    robot_account_parameter_name)
            if isinstance(stack, DeploymentFlavorStack) and not stack.env_files:
                self._create_vnf_prefix_in_file(stack)

            prepared_envs = self._get_prepared_envs(stack)
            created_stack = self.connection.create_stack(
                name=stack.name,
                template_file=stack.yaml_file,
                environment_files=prepared_envs,
                wait=wait,
                rollback=rollback)

            PreparedEnvironments.clear_stack_environments(stack)

            if wait:
                self._verify_stack_created(created_stack)

            return created_stack.get('outputs')

    def _verify_stack_created(self, created_stack):
        if created_stack.stack_status != StackStatus.CREATE_COMPLETE:
            exc_msg = "Stack {} creation failed: {}"
            raise OpenstackException(exc_msg.format(
                created_stack.name, created_stack.stack_status_reason))

    def _get_prepared_envs(self, stack):
        result = []
        result += stack.env_files or []
        result += PreparedEnvironments.get_stack_environments(stack)
        return result

    def _create_vnf_prefix_in_file(self, stack):
        params = {}
        self._assign_correct_vnf_prefix(stack, params)
        new_path = save_dict_as_yaml(params, prefix='vnf_prefix.env')
        PreparedEnvironments.add_stack_environment(stack, new_path)

    def _create_robot_account_in_file(self,
                                      stack,
                                      robot_account_parameter_name):
        robot_environment = {'parameters': {}}
        ConfigurationModifier.inject_robot_account(
            robot_environment, robot_account_parameter_name)

        new_path = save_dict_as_yaml(robot_environment,
                                     prefix='robot_account.env')
        PreparedEnvironments.add_stack_environment(stack, new_path)

    def create(self,
               stack,  # type: Union[DeploymentNetworkStack, DeploymentVnfStack, DeploymentFlavorStack]
               inject_robot=False,  # type: bool
               robot_account_parameter_name=ROBOT_ACCOUNT_PARAM_NAME  # type: str
               ):
        warn_msg = "`Stack.create` method is deprecated. " \
                   "Use `Stack.create_stack` keyword instead."
        logging.warning(warn_msg)
        self._verify_stack_configuration_exists(stack)

        if isinstance(stack, DeploymentVnfStack):
            return self._create_vnf_stack(
                stack, inject_robot, robot_account_parameter_name)
        elif isinstance(stack, DeploymentFlavorStack):
            return self._create_flavor_stack(stack)
        elif isinstance(stack, DeploymentNetworkStack):
            return self._create_network_stack(stack)

    def _create_network_stack(self, stack):
        return self._create(stack, resource_registry={})

    def _create_flavor_stack(self, stack):
        self._assign_correct_vnf_prefix(stack, stack.configuration_data)
        return self._create(stack, resource_registry={})

    def _create_vnf_stack(self,
                          stack,
                          inject_robot,
                          robot_account_parameter_name):
        resource_registry = self._get_resource_registry(stack)

        self._inject_robot_account(
            stack.configuration_data,
            inject_robot,
            robot_account_parameter_name)

        return self._create(stack, resource_registry)

    def _create(self, stack, resource_registry):
        yaml_path = stack.yaml_file
        template = load_yaml(yaml_path)

        configuration_directory = os.path.dirname(yaml_path)
        files = self.get_referenced_files(configuration_directory)
        self._assign_template_version(template)

        heat = self.connection.orchestration
        attrs = {'stack_name': stack.name,
                 'template': template,
                 'files': files,
                 'environment': json.dumps(resource_registry)}

        config_data = self._get_configuration_data_without_resource_registry(
            stack)
        attrs.update(config_data)

        created_stack = heat._create(_Stack, **attrs)
        self._wait_for_stack_creation(created_stack)
        stack_with_outputs = self.find_stack(name_or_id=created_stack.id)
        return stack_with_outputs.outputs

    def _get_configuration_data_without_resource_registry(self, stack):
        # We want to remove resource_registry key from configuration_data,
        # because we pass it as 'environment' key in stack creation.
        res_reg = 'resource_registry'
        configuration_data = stack.configuration_data.copy()
        if res_reg in configuration_data:
            configuration_data.pop(res_reg)
        return configuration_data

    def _verify_stack_configuration_exists(self, stack):
        if stack.configuration_data is None:
            exc_msg = "Stack's configuration_data is not loaded. " \
                      "Stack's name: {}".format(stack.name)
            raise TypeError(exc_msg)

    def _inject_robot_account(
            self,
            configuration_data,
            inject_robot,
            robot_account_parameter_name):
        if inject_robot:
            ConfigurationModifier.inject_robot_account(
                configuration_data, robot_account_parameter_name)

    def _assign_correct_vnf_prefix(self, stack, configuration_data):
        parameters = 'parameters'
        vnf_prefix = 'vnf_prefix'
        default_prefix = stack.default_vnf_prefix

        if parameters in configuration_data:
            params = configuration_data[parameters]
            if vnf_prefix in params and params[vnf_prefix] is None:
                params[vnf_prefix] = default_prefix
        elif default_prefix is not None:
            configuration_data[parameters] = {vnf_prefix: default_prefix}

    def _get_resource_registry(self, stack):
        """
        Returns dictionary with `resource_registry` key and a value that
        is found in stack's resource_registry attribute.
        """
        res_reg = 'resource_registry'
        resource_registry = {res_reg: stack.resource_registry}

        return resource_registry

    def _assign_template_version(self, template):
        if self.HEAT_TEMPLATE_VERSION in template:
            template[self.HEAT_TEMPLATE_VERSION] = str(
                template[self.HEAT_TEMPLATE_VERSION])
